	/** 
	 * jumpstart the process by instantiating2 Promotion
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		promotionId = PromotionService.getPromotionInstance()
		.createPromotion( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		PromotionService.getPromotionInstance()
				.createPromotion( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.promotionSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Promotion : " + successValue.getPromotionId());
							  if (successValue.getPromotionId().equals(promotionId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfPromotionList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Promotion test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on promotion consumed")
					);
			subscriber.promotionSubscribe( promotionId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Promotion : " + successValue.getPromotionId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfPromotionList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on promotion for promotionId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Promotion. 
	 */
	protected Promotion read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Promotion" );

		Promotion entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Promotion with primary key" );
		msg.append( promotionId );
		
		PromotionFetchOneSummary fetchOneSummary = new PromotionFetchOneSummary( promotionId );

		try {
			entity = PromotionService.getPromotionInstance().getPromotion( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Promotion " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Promotion.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Promotion." );

		StringBuilder msg = new StringBuilder( "Failed to update a Promotion : " );        
		Promotion entity = read();
		UpdatePromotionCommand command = generateUpdateCommand();
		command.setPromotionId(entity.getPromotionId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Promotion." );

			// for use later on...
			promotionId = entity.getPromotionId();

			PromotionService proxy = PromotionService.getPromotionInstance();  

			proxy.updatePromotion( command ).get();

			LOGGER.info( "-- Successfully saved Promotion - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + promotionId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Promotion.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Promotion." );

		Promotion entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Promotion with id " + promotionId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Promotion with id " + promotionId );

			throw e;
		}

		try{
			PromotionService.getPromotionInstance().delete( new DeletePromotionCommand( entity.getPromotionId() ) ).get();
			LOGGER.info( "-- Successfully deleted Promotion with id " + promotionId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Promotion with id " + promotionId );

			throw e;
		}
	}

	/**
	 * get all Promotions.
	 */
	protected List<Promotion> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Promotions:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Promotion : " );        
		List<Promotion> collection  = new ArrayList<>();

		try {
			// call the static get method on the PromotionService
			collection = PromotionService.getPromotionInstance().getAllPromotion();
			assertNotNull( collection, "An Empty collection of Promotion was incorrectly returned.");
			
			// Now print out the values
			Promotion entity = null;            
			Iterator<Promotion> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getPromotionId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

